# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
from author_batch200_root_rap_a import R,D,T,U,N,S,H
C=R+[['拉丁 rapax，词干 rapaci- → 英语 rapacious','爱抓取、贪婪的 → 贪得无厌、掠夺性的']]
V=R+[['通俗拉丁 *rapire → 古法语 ravir／ravage／ravager','猛地带走 → 毁坏、蹂躏'],['英语 ravage','严重破坏；造成的破坏']]
WB=[
E('ravenously','/ˈrævənəsli/','狼吞虎咽地；极其饥饿地；如饥似渴地','那种很强的饥饿或渴望，已经直接表现在吃或获取的动作里。','ravenous + -ly。',H(N,'英语 ravenous → ravenously','饥饿极了的 → 狼吞虎咽地、如饥似渴地'),'eat ravenously 是饿得大口吃；read ravenously 是如饥似渴地阅读。后者把食欲的画面转给求知欲，读者不必真的在吃书。','eat ravenously；ravenously hungry；read ravenously。','greedily 可以带贪心意味；ravenously 常先让人想到极度饥饿或强烈求知欲，未必责备这个人。',('They ate ravenously after the long hike.','长途徒步后，他们狼吞虎咽地吃起来。'),('She read ravenously, borrowing new books every week.','她如饥似渴地阅读，每周都会借新书。'),sources=['https://en.wiktionary.org/wiki/ravenously','https://www.etymonline.com/word/ravenous']),
E('rapacious','/rəˈpeɪʃəs/','贪婪掠夺的；攫取无度的','手一直向外伸，想把更多东西抓到自己这边，很少顾及别人还剩什么。','接拉丁 rapax“贪婪、爱抓取的”的词干 rapaci-，再接英语 -ous；远源 rapere“夺取”。',C,'rapacious greed 是强烈而带掠夺性的贪欲；rapacious landlords 是作者对不断攫取利益的房东的严厉批评。这个词通常不是中性描述进取心，而是带明显贬义。','rapacious greed；rapacious behaviour；a rapacious appetite for wealth。','ambitious 可以是有抱负；rapacious 通常指不顾别人而贪婪攫取，批评力度更强。',('The novel portrays a rapacious landlord who cares only about rent.','小说描写了一个贪得无厌、只在乎租金的房东。'),('The report criticised the company’s rapacious use of local resources.','报告批评了该公司对当地资源的掠夺式利用。'),sources=['https://www.etymonline.com/word/rapacious']),
E('rapacity','/rəˈpæsəti/','贪婪；掠夺性；攫取无度','不是一次想多拿一点，而是不断攫取、不知满足的那种倾向。','经法语 rapacité 接拉丁 rapacitas，来自 rapax；与 rapacious 是同族，但英语名词有自己的借入路线。',R+[['拉丁 rapax → rapacitas → 法语 rapacité','贪婪的 → 贪婪、掠夺性'],['英语 rapacity','贪得无厌的倾向或行为']],'the rapacity of an empire 是对帝国攫取无度的批评；unchecked rapacity 是没有约束的贪欲。它偏正式，常用于历史、评论或文学，不只是普通“胃口好”。','unchecked rapacity；human rapacity；the rapacity of。','greed 是普通的贪婪；rapacity 往往让人想到主动夺取、侵占的行为色彩。',('The historian describes the rapacity of the invading army.','历史学家描写了入侵军队的掠夺性。'),('The satire exposes the character’s vanity and rapacity.','这篇讽刺作品揭露了人物的虚荣和贪婪。'),sources=['https://www.etymonline.com/word/rapacity']),
E('rapaciously','/rəˈpeɪʃəsli/','贪婪地攫取；掠夺性地','把“还要更多”的欲望变成行动，伸手获取时几乎不顾他人。','rapacious + -ly。',H(C,'英语 rapacious → rapaciously','贪婪掠夺的 → 贪婪掠夺地'),'consume rapaciously 是以极度贪婪、耗夺的方式消耗；grab rapaciously 则是贪婪地抢取。这个副词带强烈评价，比简单说 eagerly“急切地”更负面。','exploit rapaciously；consume rapaciously；seize rapaciously。','eagerly 只说渴望、积极；rapaciously 指向不顾限度或他人利益的攫取。',('The fictional ruler seized land rapaciously.','故事中的统治者贪婪地侵占土地。'),('The essay criticises an economy that consumes resources rapaciously.','这篇文章批评了一种掠夺式消耗资源的经济模式。'),sources=['https://www.etymonline.com/word/rapacious','https://en.wiktionary.org/wiki/rapaciously']),
E('rapaciousness','/rəˈpeɪʃəsnəs/','贪婪掠夺的性质；攫取无度','把一个人或一种做法“总想抓取更多”的特点单独提出来说。','rapacious + -ness，形成性质名词。',H(C,'英语 rapacious → rapaciousness','贪婪掠夺的 → 这种贪婪掠夺性'),'rapaciousness 与 rapacity 很接近，常是对态度或行为的强烈批评。前者的英语构词比较透明，后者有法语、拉丁名词的借入历史，不能硬分成两种不同贪欲。','the rapaciousness of；ruthless rapaciousness。','rapacity 与 rapaciousness 基本近义；较长的形式不意味着贪婪程度更深。',('The fable condemns the wolf’s rapaciousness.','这则寓言谴责了狼的贪婪掠夺性。'),('Her speech attacked the rapaciousness of the scheme.','她的演讲抨击了这项计划中的掠夺性。'),sources=['https://en.wiktionary.org/wiki/rapaciousness','https://www.etymonline.com/word/rapacious']),
E('raptor','英 /ˈræptə/；美 /ˈræptər/','猛禽；某些恐龙的通俗称呼','先看到一个动作：猛地伸爪抓住猎物，把它带走。','拉丁 raptor 是 rapere“夺取”的施事名词，表示抢夺者、捕食者；英语又把它用于猛禽。恐龙用法常是 Velociraptor 等名称的简称。',R+[['拉丁 raptor → 英语 raptor','抓取者、捕食者 → 猛禽'],['恐龙名称的相关简称 raptor','某些捕食性恐龙的通俗称呼']],'鹰、隼等鸟类语境中的 raptor 通常译猛禽。恐龙展览里的 raptor 可能指驰龙类一类动物或某个名称的简称，要看上下文；不要见到这个词就一律想成电影里的恐龙。','a bird of prey／a raptor；raptor conservation；a raptor fossil。','predator 指捕食者，范围很广；现代鸟类语境的 raptor 特指猛禽，不包括所有吃动物的生物。',('The centre cares for injured raptors, including hawks and owls.','这个中心照料受伤的猛禽，包括鹰和猫头鹰。'),('The guide explained that the word raptor can also appear in dinosaur names.','讲解员说明，raptor 也会出现在恐龙名称中。'),sources=['https://en.wiktionary.org/wiki/raptor','https://www.merriam-webster.com/dictionary/raptor']),
E('raptorial','/ræpˈtɔːriəl/','捕食性的；适于抓捕猎物的；猛禽的','爪子或前肢的形状，让它能一把夹住、抓牢猎物。','接新拉丁 raptorius“捕食性的” + -al；raptorius 来自拉丁 raptor。现代可联系 raptor，但不只是英语人名词直接加 -ial。',R+[['拉丁 raptor → 新拉丁 raptorius','抓取者 → 适于捕食、抓取的'],['英语 raptorial','猛禽的；适于抓捕猎物的']],'raptorial claws 是抓猎物的爪；昆虫的 raptorial forelegs 是适于抓捕的前足。这说明它不只用于鸟，也可以描述别的动物的抓捕结构。','raptorial birds；raptorial claws；raptorial forelegs。','raptor 是名词；raptorial 是形容词，既能说猛禽，也能说其他动物适于抓捕猎物的部位。',('The diagram shows the mantis’s raptorial forelegs.','图中展示了螳螂用于抓捕猎物的前足。'),('The class compared the feet of raptorial birds with those of ducks.','课堂比较了猛禽的足和鸭子的足。'),sources=['https://www.merriam-webster.com/dictionary/raptorial']),
E('ravine','/rəˈviːn/','深而狭窄的沟谷；峡沟','急水一路冲刷、带走泥土和岩屑，留下两侧较陡的一道深沟。','经法语 ravin、ravine 接拉丁 rapina“抢夺”；法语中从冲夺、急水发展到被水冲出的沟谷，也受到 rapidus“迅疾”的影响。',R+[['拉丁 rapina → 古法语 ravine／raviner','掠夺、猛烈冲夺 → 急水、冲刷'],['法语 ravin／ravine → 英语 ravine','急水冲出的深沟、沟谷']],'a narrow ravine 是一条狭窄深沟。这个词把注意力放在地形，不是在说那里一定此刻有大水；水流留下的沟谷可以在干燥时仍然存在。','a deep ravine；cross a ravine；the bottom of a ravine。','valley 是较宽泛的山谷；ravine 通常强调深、窄、两侧较陡，并与流水侵蚀有关。',('A narrow bridge crossed the ravine.','一座窄桥横跨沟谷。'),('We could hear a stream at the bottom of the ravine.','我们能听见沟谷底部的溪水声。'),sources=['https://www.etymonline.com/word/ravine']),
E('ravage','/ˈrævɪdʒ/','蹂躏；严重破坏；破坏造成的损害','像一股力量横扫过去，把原来完整的地方毁坏、耗损。','法语 ravager、ravage 接 ravir“猛地带走”，最终接拉丁 rapere；名词和动词分别有法语借入支线。',V,'风暴可以 ravage a coast，战事可以 ravage a region。名词常用复数 the ravages of，表示某种力量留下的破坏，如 the ravages of time“岁月的侵蚀”。这个词强于一般 damage。','ravage a region；be ravaged by；the ravages of time。','ravage 是严重破坏；ravish 的常见形容词 ravishing 却可以是美得令人陶醉，不能因拼写接近而互换。',('The storm ravaged the exposed coastline.','风暴严重破坏了暴露在风中的海岸线。'),('The old building showed the ravages of time.','这栋老建筑显露出岁月侵蚀的痕迹。'),sources=['https://www.etymonline.com/word/ravage']),
E('ravager','英 /ˈrævɪdʒə/；美 /ˈrævɪdʒər/','蹂躏者；破坏者；造成严重毁坏的力量','顺着 ravage 找到动作的来源：是谁或什么在造成那一片破坏。','ravage + -er；英语是施事名词，法语同拼写 ravager 则是动词，不能把两种语言的词性混在一起。',H(V,'英语 ravage + -er → ravager','造成严重破坏 → 破坏者、蹂躏者'),'a ravager of forests 可以指毁坏森林的人或破坏性力量。这个词偏书面，也常见于小说里的角色称号；理解时先抓“造成毁坏的主体”，再看上下文指谁。','a ravager of；a destructive ravager。','ravage 是毁坏这一动作或损害；ravager 是实施或造成毁坏者。',('The legend describes the creature as a ravager of villages.','传说把这种生物描写成村庄的毁坏者。'),('The poet calls time a patient ravager of monuments.','诗人把时间称为缓缓侵蚀纪念建筑的破坏者。'),sources=['https://en.wiktionary.org/wiki/ravager','https://www.etymonline.com/word/ravage']),
E('rapine','/ˈræpaɪn/','抢掠；掠夺〔正式、历史用语〕','不是正常交换，而是用强力把别人的财物夺走。','经古法语 rapine 或直接借入拉丁 rapina“掠夺”，来自 rapere“夺取”。',R+[['拉丁 rapina → 古法语 rapine → 英语 rapine','夺取财物 → 掠夺、抢掠']],'rapine 常出现在战争、历史或文学叙述中，强调暴力掠夺。现代日常表达通常会用 plunder、looting 等更常见的词；它不等于轻微顺手拿错东西。','pillage and rapine；acts of rapine；a campaign of rapine。','rapine 与 ravine 有共同的拉丁背景，但前者保留抢掠义，后者走向急水冲成的地形。',('The chronicle describes a period of violence and rapine.','编年史描写了一段充满暴力与抢掠的时期。'),('The historian distinguished organised conquest from uncontrolled rapine.','历史学家区分了有组织的征服与失控的抢掠。'),sources=['https://www.etymonline.com/word/ravine','https://en.wiktionary.org/wiki/rapine']),
]
